    assert_eq!(s.keys_with_prefix("cfg:"), vec!["cfg:mode", "cfg:name"]);
    assert_eq!(s.keys_with_prefix("cfg:m"), vec!["cfg:mode"]);
    assert_eq!(s.keys_with_prefix("CFG"), Vec::<String>::new());
    assert_eq!(s.keys_with_prefix(""), s.keys());
